begin;
select no_plan();
insert into auth.users(id) values ('18000000-0000-4000-8000-000000000001'), ('18000000-0000-4000-8000-000000000002');
insert into public.app_settings(owner_user_id) values ('18000000-0000-4000-8000-000000000001');
select lives_ok($$select public.acquire_direct_banking_sync('18000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000011','revolut')$$,'direct bank acquires');
select lives_ok($$select public.acquire_banking_sync('18000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000012')$$,'Qonto independently acquires');
select lives_ok($$select public.renew_banking_sync('18000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000011')$$,'renew finds correct provider by run');
select throws_ok($$select public.acquire_direct_banking_sync('18000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000013','revolut')$$,'P0001','SYNC_LOCKED','same provider locked');
select throws_ok($$select public.acquire_direct_banking_sync('18000000-0000-4000-8000-000000000002','18000000-0000-4000-8000-000000000014','bunq')$$,'42501','DATABASE_ERROR','nonowner denied');
select throws_ok($$select public.acquire_direct_banking_sync('18000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000014','arbitrary')$$,'P0001','DATABASE_ERROR','unknown provider denied');
select public.stage_banking_page('18000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000011','accounts',null,1,null,'[]');
select lives_ok($$select public.publish_banking_sync('18000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000011')$$,'direct bank publishes');
select is((select status from public.integrations where provider='qonto'),'syncing','publication does not change Qonto');
select public.acquire_direct_banking_sync('18000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000015','pennylane');
create function pg_temp.invoice(p_id text default 'pl1', p_number text default 'PL-001', p_paid bigint default 6000) returns jsonb language sql as $$
select jsonb_build_array(jsonb_build_object('externalId',p_id,'customer',jsonb_build_object('externalId','c1','name','API client'),'invoiceNumber',p_number,'issuedAt','2026-09-01','dueAt','2026-09-30','amountHtCents',10000,'amountVatCents',2000,'amountTtcCents',12000,'currency','EUR','status','partially_paid','payment',jsonb_build_object('kind','known','paidAmountCents',p_paid,'paidAt',null))) $$;
select lives_ok($$select public.publish_pennylane_sync('18000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000015',pg_temp.invoice())$$,'invoices publish atomically');
select is((select paid_amount_cents from public.invoices where provider='pennylane'),6000::bigint,'provider settlement imported');
select is((select count(*) from public.invoice_payments),0::bigint,'no invented payment date or payment event');
select lives_ok($$select public.publish_pennylane_sync('18000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000015',pg_temp.invoice())$$,'successful response replay idempotent');
select public.acquire_direct_banking_sync('18000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000016','pennylane');
select throws_ok($$select public.publish_pennylane_sync('18000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000016',pg_temp.invoice('pl2','PL-002') || pg_temp.invoice('pl3','PL-001'))$$,'P0001','DATABASE_ERROR','invoice number collision rolls back entire snapshot');
select is((select count(*) from public.invoices),1::bigint,'failed batch leaves prior invoices unchanged');
select lives_ok($$select public.publish_pennylane_sync('18000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000016',pg_temp.invoice('pl1','PL-001',12000))$$,'same external identity updates');
select is((select count(*) from public.customers),1::bigint,'customer identities deduplicate');
select is((select count(*) from public.invoices),1::bigint,'invoice identities deduplicate');
select is((select paid_amount_cents from public.invoices),12000::bigint,'settlement refreshes');
set local role authenticated;
select set_config('request.jwt.claim.sub','18000000-0000-4000-8000-000000000001',true);
select throws_ok($$update public.invoices set paid_amount_cents=0 where provider='pennylane'$$,'P0001','FC_PROVIDER_MANAGED','imported invoices cannot be edited locally');
select throws_ok($$insert into public.invoice_payments(owner_user_id,invoice_id,amount_cents,paid_at) select owner_user_id,id,1,current_date from public.invoices where provider='pennylane'$$,'P0001','FC_PROVIDER_MANAGED','manual payment cannot override provider balance');
select throws_ok($$select public.acquire_direct_banking_sync('18000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000020','bunq')$$,'42501',null,'direct sync RPC is server-only');
reset role;
select * from finish();
rollback;
